// Подготавливаем тело для вывода, скрывая пароль и JWT.
function displayBody(text) {
    try {
        return JSON.stringify(JSON.parse(text), function (key, value) {
            if (key === "password" || key === "access_token") {
                return "<hidden>";
            }
            return value;
        }, 2);
    } catch (error) {
        // Ответы 401/403 содержат обычный текст, а не JSON.
        return text;
    }
}

